using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using System;using System.Linq;
public static class FixFurinaURP {
[MenuItem("Tools/Characters/Fix Furina View")]
public static void Fix(){
string path="Assets/Game/Characters/BlenderAlternate";foreach(var g in AssetDatabase.FindAssets("t:Material",new[]{path})){var m=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(g));var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(path+"/Textures/"+m.name.Replace("Furina_","")+".png");if(tex)m.SetTexture("_BaseMap",tex);EditorUtility.SetDirty(m);}
var p=GameObject.Find("Furina Player");foreach(var t in Terrain.activeTerrains)Debug.Log("URP_TERRAIN "+t.name+" "+t.transform.position+" size="+t.terrainData.size);
foreach(var terrain in Terrain.activeTerrains){var col=terrain.GetComponent<TerrainCollider>();if(!col)col=terrain.gameObject.AddComponent<TerrainCollider>();col.terrainData=terrain.terrainData;var origin=p.transform.position;bool placed=false;for(int ring=0;ring<25&&!placed;ring++)for(int a=0;a<16&&!placed;a++){float angle=a*Mathf.PI/8;var candidate=origin+new Vector3(Mathf.Cos(angle)*ring*8,0,Mathf.Sin(angle)*ring*8);var local=candidate-terrain.transform.position;float u=local.x/terrain.terrainData.size.x,v=local.z/terrain.terrainData.size.z;if(u<0||u>1||v<0||v>1)continue;float h=terrain.terrainData.GetInterpolatedHeight(u,v)+terrain.transform.position.y;if(h<0||terrain.terrainData.GetSteepness(u,v)>28)continue;candidate.y=h+.05f;var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=candidate;cc.enabled=true;placed=true;}if(placed)break;}Physics.SyncTransforms();
var hits=Physics.RaycastAll(new Vector3(p.transform.position.x,1000,p.transform.position.z),Vector3.down,3000,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).ToArray();foreach(var h in hits.Take(8))Debug.Log("URP_GROUND "+h.collider.name+" "+h.point);
var ground=GameObject.Find("Terrain");if(ground)foreach(var r in ground.GetComponentsInChildren<Renderer>().Take(3))Debug.Log("URP_RENDER "+r.name+" "+r.bounds);
if(hits.Length>0){var good=hits.FirstOrDefault(h=>h.collider is TerrainCollider && h.normal.y>.7f);if(good.collider){var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=good.point+Vector3.up*.05f;cc.enabled=true;}}
var cam=Camera.main;cam.usePhysicalProperties=false;cam.fieldOfView=55;var data=cam.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>();if(data)data.renderPostProcessing=true; foreach(var v in UnityEngine.Object.FindObjectsByType<UnityEngine.Rendering.Volume>()){if(!v.sharedProfile)continue;var original=v.sharedProfile;var copy=UnityEngine.Object.Instantiate(original);copy.name=original.name+"_CharacterCamera";copy.components=new System.Collections.Generic.List<UnityEngine.Rendering.VolumeComponent>();foreach(var c in original.components){var cc=UnityEngine.Object.Instantiate(c);if(cc is UnityEngine.Rendering.Universal.DepthOfField || cc is UnityEngine.Rendering.Universal.MotionBlur)cc.active=false;copy.components.Add(cc);}string vp=AssetDatabase.GenerateUniqueAssetPath("Assets/Game/"+copy.name+".asset");AssetDatabase.CreateAsset(copy,vp);foreach(var c in copy.components)AssetDatabase.AddObjectToAsset(c,copy);v.sharedProfile=copy;if(PrefabUtility.IsPartOfPrefabInstance(v))PrefabUtility.RecordPrefabInstancePropertyModifications(v);}cam.GetComponent<Game.ThirdPerson.ThirdPersonFollowCamera>().UpdateView(1);
EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Debug.Log("URP_VIEW_FIXED "+p.transform.position);
}}



